118	/** Parse "HH:MM" → total minutes */
119	function timeToMin(t: string): number {
120	  const [h, m] = t.split(":").map(Number);
121	  return h * 60 + m;
122	}
123	
124	/** Format total minutes → "HH:MM" */
125	function minToTime(mins: number): string {
126	  const h = Math.floor(mins / 60);
127	  const m = mins % 60;
128	  return `${h.toString().padStart(2, "0")}:${m.toString().padStart(2, "0")}`;
129	}
