157	router.get("/courts", async (req, res): Promise<void> => {
158	  const params = ListCourtsQueryParams.safeParse(req.query);
159	  if (!params.success) {
160	    res.status(400).json({ error: params.error.message });
161	    return;
162	  }
163	
164	  const conditions: ReturnType<typeof eq>[] = [];
165	
166	  // If ownerUserId filter is supplied, this is an owner dashboard request.
167	  // Require the caller to be authenticated as that owner (or an admin).
168	  if (params.data.ownerUserId) {
169	    const userId = getCurrentUserId(req);
170	    if (!userId) {
171	      res.status(401).json({ error: "Unauthorized" });
172	      return;
173	    }
174	    const role = await getUserRole(userId);
175	    if (role !== "admin" && userId !== params.data.ownerUserId) {
176	      res.status(403).json({ error: "Forbidden" });
177	      return;
178	    }
179	  } else {
180	    // Public callers only see active/approved courts.
181	    conditions.push(inArray(courtsTable.status, ["approved", "active"]));
182	  }
183	
184	  if (params.data.type) conditions.push(eq(courtsTable.type, params.data.type));
185	  if (params.data.surface) conditions.push(eq(courtsTable.surface, params.data.surface));
186	  if (params.data.condition) conditions.push(eq(courtsTable.condition, params.data.condition));
187	  if (params.data.isIndoor != null) conditions.push(eq(courtsTable.isIndoor, params.data.isIndoor));
188	  if (params.data.minPrice != null) conditions.push(gte(courtsTable.pricePerHour, String(params.data.minPrice)));
189	  if (params.data.maxPrice != null) conditions.push(lte(courtsTable.pricePerHour, String(params.data.maxPrice)));
190	
191	  if (params.data.ownerUserId) {
192	    // Authenticated owner/admin view — join facilities to filter by owner and return full data.
193	    const facilityConditions = [eq(facilitiesTable.ownerUserId, params.data.ownerUserId)];
194	    if (params.data.city) facilityConditions.push(eq(facilitiesTable.city, params.data.city));
195	
196	    const rows = await db
197	      .select({ court: courtsTable, facility: facilitiesTable })
198	      .from(courtsTable)
199	      .innerJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
200	      .where(and(...conditions, ...facilityConditions));
201	
202	    const courtIds = rows.map(r => r.court.id);
203	    const photoMap = new Map<number, string[]>();
204	    const ownerPricingMinMap = new Map<number, number>();
205	    if (courtIds.length > 0) {
206	      const [photos, pricingRows] = await Promise.all([
207	        db
208	          .select({ courtId: courtPhotosTable.courtId, url: courtPhotosTable.url })
209	          .from(courtPhotosTable)
210	          .where(inArray(courtPhotosTable.courtId, courtIds))
211	          .orderBy(asc(courtPhotosTable.displayOrder), asc(courtPhotosTable.createdAt)),
212	        db
213	          .select({ courtId: courtPricingTable.courtId, price: courtPricingTable.price })
214	          .from(courtPricingTable)
215	          .where(and(
216	            inArray(courtPricingTable.courtId, courtIds),
217	            gte(courtPricingTable.startTime, "06:00"),
218	            lte(courtPricingTable.startTime, "23:00"),
219	          )),
220	      ]);
221	      for (const p of photos) {
222	        const arr = photoMap.get(p.courtId) ?? [];
223	        if (arr.length < 3) arr.push(p.url);
224	        photoMap.set(p.courtId, arr);
225	      }
226	      for (const entry of pricingRows) {
227	        const hourly = Number(entry.price) * 2;
228	        const prev = ownerPricingMinMap.get(entry.courtId);
229	        if (prev === undefined || hourly < prev) ownerPricingMinMap.set(entry.courtId, hourly);
230	      }
231	    }
232	
233	    res.json(rows.map(r => ({
234	      ...formatCourt(r.court, r.facility),
235	      photos: photoMap.get(r.court.id) ?? [],
236	      minDisplayPrice: ownerPricingMinMap.get(r.court.id) ?? Number(r.court.pricePerHour),
237	    })));
238	    return;
239	  }
240	
241	  // Public view: courts must belong to a verified facility.
242	  const facilityConditions: ReturnType<typeof eq>[] = [];
243	  if (params.data.city) facilityConditions.push(eq(facilitiesTable.city, params.data.city));
244	
245	  const rows = await db
246	    .select({ court: courtsTable, facility: facilitiesTable })
247	    .from(courtsTable)
248	    .innerJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
249	    .where(and(...conditions, ...facilityConditions));
250	
251	  const filtered = rows.filter(r => r.facility.verificationStatus === "active");
252	
253	  const courtIds = filtered.map(r => r.court.id);
254	  const photoMap = new Map<number, string[]>();
255	  const pricingMinMap = new Map<number, number>();
256	  if (courtIds.length > 0) {
257	    const [photos, pricingRows] = await Promise.all([
258	      db
259	        .select({ courtId: courtPhotosTable.courtId, url: courtPhotosTable.url })
260	        .from(courtPhotosTable)
261	        .where(inArray(courtPhotosTable.courtId, courtIds))
262	        .orderBy(asc(courtPhotosTable.displayOrder), asc(courtPhotosTable.createdAt)),
263	      db
264	        .select({ courtId: courtPricingTable.courtId, price: courtPricingTable.price })
265	        .from(courtPricingTable)
266	        .where(and(
267	          inArray(courtPricingTable.courtId, courtIds),
268	          // Bait-and-switch guard: only consider slots a normal human can book (06:00–23:00)
269	          gte(courtPricingTable.startTime, "06:00"),
270	          lte(courtPricingTable.startTime, "23:00"),
271	        )),
272	    ]);
273	    for (const p of photos) {
274	      const arr = photoMap.get(p.courtId) ?? [];
275	      if (arr.length < 3) arr.push(p.url);
276	      photoMap.set(p.courtId, arr);
277	    }
278	    // Pricing entries store per-30-min prices; multiply × 2 to get an hourly rate for display
279	    for (const entry of pricingRows) {
280	      const hourly = Number(entry.price) * 2;
281	      const prev = pricingMinMap.get(entry.courtId);
282	      if (prev === undefined || hourly < prev) pricingMinMap.set(entry.courtId, hourly);
283	    }
284	  }
285	
286	  res.json(filtered.map(r => ({
287	    ...formatPublicCourt(r.court, r.facility),
288	    facilityVerified: r.facility.verificationStatus === "active",
289	    photos: photoMap.get(r.court.id) ?? [],
290	    // minDisplayPrice: lowest hourly rate from custom pricing; falls back to pricePerHour
291	    minDisplayPrice: pricingMinMap.get(r.court.id) ?? Number(r.court.pricePerHour),
292	  })));
293	});
