341	// GET /courts/available-for-slot?date=YYYY-MM-DD&startTime=HH:MM&endTime=HH:MM&sport=tennis
342	// Returns court IDs that have no confirmed/blocked booking conflicts in the requested window.
343	router.get("/courts/available-for-slot", async (req, res): Promise<void> => {
344	  const { date, startTime, endTime, sport } = req.query as Record<string, string | undefined>;
345	  if (!date || !startTime || !endTime) {
346	    res.status(400).json({ error: "date, startTime, endTime are required" });
347	    return;
348	  }
349	
350	  const courtConditions: ReturnType<typeof eq>[] = [
351	    or(eq(courtsTable.status, "approved"), eq(courtsTable.status, "active"))!,
352	  ];
353	  if (sport && sport !== "all") courtConditions.push(eq(courtsTable.type, sport));
354	
355	  const allCourts = await db
356	    .select({ id: courtsTable.id })
357	    .from(courtsTable)
358	    .where(and(...courtConditions));
359	
360	  if (!allCourts.length) {
361	    res.json({ availableCourtIds: [] });
362	    return;
363	  }
364	
365	  const courtIds = allCourts.map(c => c.id);
366	
367	  const [conflictBookings, conflictBlocked] = await Promise.all([
368	    db
369	      .select({ courtId: bookingsTable.courtId })
370	      .from(bookingsTable)
371	      .where(and(
372	        inArray(bookingsTable.courtId, courtIds),
373	        eq(bookingsTable.date, date),
374	        sql`${bookingsTable.startTime} < ${endTime}`,
375	        sql`${bookingsTable.endTime} > ${startTime}`,
376	        or(
377	          eq(bookingsTable.status, "confirmed"),
378	          eq(bookingsTable.status, "blocked"),
379	          eq(bookingsTable.status, "awaiting_players"),
380	          and(
381	            eq(bookingsTable.status, "pending"),
382	            sql`${bookingsTable.createdAt} > NOW() - INTERVAL '15 minutes'`
383	          )
384	        )
385	      )),
386	    db
387	      .select({ courtId: courtBlockedSlotsTable.courtId })
388	      .from(courtBlockedSlotsTable)
389	      .where(and(
390	        inArray(courtBlockedSlotsTable.courtId, courtIds),
391	        eq(courtBlockedSlotsTable.date, date),
392	        sql`${courtBlockedSlotsTable.startTime} < ${endTime}`,
393	        sql`${courtBlockedSlotsTable.endTime} > ${startTime}`,
394	      )),
395	  ]);
396	
397	  const conflictIds = new Set([
398	    ...conflictBookings.map(b => b.courtId),
399	    ...conflictBlocked.map(b => b.courtId),
400	  ]);
401	
402	  const availableCourtIds = courtIds.filter(id => !conflictIds.has(id));
403	  res.json({ availableCourtIds });
404	});
