438	router.put("/courts/:id", requireAuth, async (req, res): Promise<void> => {
439	  const params = UpdateCourtParams.safeParse(req.params);
440	  if (!params.success) {
441	    res.status(400).json({ error: params.error.message });
442	    return;
443	  }
444	
445	  const body = UpdateCourtBody.safeParse(req.body);
446	  if (!body.success) {
447	    res.status(400).json({ error: body.error.message });
448	    return;
449	  }
450	
451	  // Ownership check via facility
452	  const [existing] = await db.select().from(courtsTable).where(eq(courtsTable.id, params.data.id));
453	  if (!existing) {
454	    res.status(404).json({ error: "Court not found" });
455	    return;
456	  }
457	
458	  const facility = await getFacility(existing.facilityId);
459	  if (!(await isOwner(req, facility?.ownerUserId ?? null))) {
460	    res.status(403).json({ error: "Forbidden – you do not own this court" });
461	    return;
462	  }
463	
464	  // Preserve extra owner-settable fields that aren't in the Zod schema
465	  const extraFields: Record<string, unknown> = {};
466	  if (typeof (req.body as any).instantBookingEnabled === "boolean") {
467	    extraFields.instantBookingEnabled = (req.body as any).instantBookingEnabled;
