471	  if ("surfaceBounce" in rb) extraFields.surfaceBounce = rb.surfaceBounce ?? null;
472	  if ("hasSmartLock" in rb) extraFields.hasSmartLock = Boolean(rb.hasSmartLock);
473	  if ("accessInstructions" in rb) extraFields.accessInstructions = rb.accessInstructions ?? null;
474	
475	  const { ...safeFields } = body.data as any;
476	
477	  const [court] = await db
478	    .update(courtsTable)
479	    .set({
480	      ...safeFields,
481	      ...extraFields,
482	      pricePerHour: String(body.data.pricePerHour),
483	
484	      rentableItems: body.data.rentableItems ?? null,
485	      amenities: body.data.amenities ?? [],
