487	      facilityId: existing.facilityId,
488	      workingHours: body.data.workingHours ?? null,
489	      amenityPhotos: body.data.amenityPhotos ?? null,
490	    })
491	    .where(eq(courtsTable.id, params.data.id))
492	    .returning();
493	
494	  if (!court) {
495	    res.status(404).json({ error: "Court not found" });
