553	
554	  const dayOfWeek = new Date(date + "T00:00:00").getDay();
555	
556	  const [pricingEntries, existingBookings, blockedSlots] = await Promise.all([
557	    db
558	      .select()
559	      .from(courtPricingTable)
560	      .where(
561	        and(
562	          eq(courtPricingTable.courtId, params.data.id),
563	          eq(courtPricingTable.dayOfWeek, dayOfWeek)
564	        )
565	      ),
566	    db
567	      .select()
568	      .from(bookingsTable)
569	      .where(
570	        and(
571	          eq(bookingsTable.courtId, params.data.id),
572	          eq(bookingsTable.date, date),
573	          or(
574	            eq(bookingsTable.status, "confirmed"),
575	            eq(bookingsTable.status, "blocked"),
576	            eq(bookingsTable.status, "awaiting_players"),
577	            and(
578	              eq(bookingsTable.status, "pending"),
579	              sql`${bookingsTable.createdAt} > NOW() - INTERVAL '15 minutes'`
580	            )
581	          )
582	        )
583	      ),
584	    db
585	      .select()
586	      .from(courtBlockedSlotsTable)
587	      .where(
588	        and(
589	          eq(courtBlockedSlotsTable.courtId, params.data.id),
590	          eq(courtBlockedSlotsTable.date, date)
591	        )
592	      ),
593	  ]);
594	
595	  // ── Parse working hours for this day ────────────────────────────────────────
596	  let openTime = "07:00";
597	  let closeTime = "22:00";
598	  let courtClosed = false;
599	
600	  if (court.workingHours) {
601	    try {
602	      const wh = JSON.parse(court.workingHours) as Record<string, { open: string; close: string; closed: boolean }>;
603	      const dayConfig = wh[String(dayOfWeek)];
604	      if (dayConfig) {
605	        if (dayConfig.closed) {
606	          courtClosed = true;
607	        } else {
608	          openTime = dayConfig.open ?? "07:00";
609	          closeTime = dayConfig.close ?? "22:00";
610	        }
611	      }
612	    } catch {
613	      // malformed JSON — fall back to defaults
614	    }
615	  }
616	
617	  if (courtClosed) {
618	    res.json(GetCourtAvailabilityResponse.parse({ courtId: params.data.id, date, slots: [] }));
619	    return;
620	  }
621	
622	  const weeklyPricingMap = new Map(pricingEntries.map(e => [e.startTime, Number(e.price)]));
623	  const defaultSlotPrice = Number(court.pricePerHour) / 2;
624	
625	  const allSlots = generateSlots(openTime, closeTime).map(({ startTime, endTime }) => {
626	    const isBooked = existingBookings.some(
627	      b => b.startTime <= startTime && b.endTime > startTime
628	    );
629	    const isBlocked = blockedSlots.some(
630	      b => b.startTime <= startTime && b.endTime > startTime
631	    );
632	
633	    // Slot price priority: weekly template > base rate fallback
634	    const price = weeklyPricingMap.has(startTime)
635	      ? weeklyPricingMap.get(startTime)!
636	      : defaultSlotPrice;
637	
638	    return { startTime, endTime, isAvailable: !isBooked && !isBlocked, price };
639	  });
640	
641	  res.json(GetCourtAvailabilityResponse.parse({
642	    courtId: params.data.id,
643	    date,
644	    slots: allSlots,
645	  }));
646	});
