724	router.get("/courts/:id/equipment-availability", async (req, res): Promise<void> => {
725	  const courtId = parseInt(String(req.params.id), 10);
726	  const { date, startTime, endTime } = req.query as Record<string, string>;
727	  if (!courtId || !date || !startTime || !endTime) {
728	    res.status(400).json({ error: "courtId, date, startTime, endTime required" });
729	    return;
730	  }
731	
732	  const [court] = await db.select().from(courtsTable).where(eq(courtsTable.id, courtId));
733	  if (!court) { res.status(404).json({ error: "Court not found" }); return; }
734	
735	  const equipment: Array<{ name: string; pricePerSlot: number; stock: number }> =
736	    court.rentableItems ? JSON.parse(court.rentableItems) : [];
737	
738	  if (equipment.length === 0) { res.json([]); return; }
739	
740	  // Find overlapping confirmed/pending bookings with rented items
741	  const existingBookings = await db
742	    .select({ rentedItems: bookingsTable.rentedItems, startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
743	    .from(bookingsTable)
744	    .where(and(eq(bookingsTable.courtId, courtId), eq(bookingsTable.date, date)));
745	
746	  // Parse startTime/endTime to minutes for overlap check
747	  const toMin = (t: string) => { const [h, m] = t.split(":").map(Number); return h * 60 + m; };
748	  const reqStart = toMin(startTime);
749	  const reqEnd = toMin(endTime);
750	
751	  // Sum up booked quantities for overlapping bookings
752	  const bookedQty: Record<string, number> = {};
753	  for (const b of existingBookings) {
754	    if (!b.rentedItems) continue;
755	    const bStart = toMin(b.startTime);
756	    const bEnd = toMin(b.endTime);
757	    // Overlap: not (bEnd <= reqStart || bStart >= reqEnd)
758	    if (bEnd <= reqStart || bStart >= reqEnd) continue;
759	    try {
760	      const items: Array<{ name: string; quantity: number }> = JSON.parse(b.rentedItems);
761	      for (const item of items) {
762	        bookedQty[item.name] = (bookedQty[item.name] ?? 0) + item.quantity;
763	      }
764	    } catch {}
765	  }
766	
767	  const result = equipment.map(e => ({
768	    name: e.name,
769	    pricePerSlot: e.pricePerSlot,
770	    stock: e.stock,
771	    booked: bookedQty[e.name] ?? 0,
772	    available: Math.max(0, e.stock - (bookedQty[e.name] ?? 0)),
773	  }));
774	
775	  res.json(result);
776	});
